from collections import defaultdict
from typing import Callable, Dict, Hashable, List, Sequence


def canonical_weak_inverse(domain: Sequence[Hashable], f: Callable[[Hashable], Hashable]) -> Callable[[Hashable], Hashable]:
    table: Dict[Hashable, Hashable] = {}
    for x in domain:
        y = f(x)
        if y not in table:
            table[y] = x
    default = domain[0]
    return lambda y: table.get(y, default)


def demo() -> None:
    domain: List[int] = list(range(8))
    f: Callable[[int], int] = lambda x: x % 3
    g = canonical_weak_inverse(domain, f)
    image = sorted({f(x) for x in domain})
    print('image =', image)
    for y in image:
        print(f'  g({y}) = {g(y)} ; f(g({y})) = {f(g(y))}')
    ok = all(f(g(f(x))) == f(x) for x in domain)
    succ = sum(1 for x in domain if f(g(f(x))) == f(x))
    print('weak inverse valid?', ok, '| successes', succ, 'of', len(domain))


if __name__ == '__main__':
    demo()

from typing import Dict, Tuple

CRYPTO_LEVELS: Tuple[str, str, str, str] = ('OWF', 'PRG', 'PRF', 'ENC')
RANK: Dict[str, int] = {'OWF': 0, 'PRG': 1, 'PRF': 2, 'ENC': 3}


def implies(a: str, b: str) -> bool:
    return RANK[a] <= RANK[b]


def demo() -> None:
    print('rank injective?', len(set(RANK.values())) == len(RANK))
    print('order total?', all(implies(a, b) or implies(b, a)
                              for a in CRYPTO_LEVELS for b in CRYPTO_LEVELS))
    print('least  =', min(CRYPTO_LEVELS, key=lambda l: RANK[l]))
    print('great. =', max(CRYPTO_LEVELS, key=lambda l: RANK[l]))
    print('     ' + ' '.join(f'{c:>4}' for c in CRYPTO_LEVELS))
    for a in CRYPTO_LEVELS:
        print(f'{a:>4} ' + ' '.join(f'{("T" if implies(a, b) else "."):>4}'
                                     for b in CRYPTO_LEVELS))


if __name__ == '__main__':
    demo()

