function EXACT_INVERSIONS(domain, f, g):
    recovered <- empty list
    for x in domain:
        if g(f(x)) == x:
            recovered.append(x)
    return recovered

function CAPACITY_AND_DEFICIT(domain, f):
    fibers <- empty map (value -> list)
    for x in domain:
        fibers[f(x)].append(x)
    image_size <- number of keys in fibers
    deficit <- sum over fibers of (len(fiber) - 1)
    assert image_size + deficit == |domain|
    return (image_size, deficit)
